<script setup lang="ts">
import {ref,computed,watch} from 'vue';
import {use} from 'echarts/core';
import {PieChart,LineChart,BarChart} from 'echarts/charts';
import {GridComponent,TooltipComponent,LegendComponent} from 'echarts/components';
import {CanvasRenderer} from 'echarts/renderers';
import VChart from 'vue-echarts';
import {managementRequest} from '../api/management';
use([PieChart,LineChart,BarChart,GridComponent,TooltipComponent,LegendComponent,CanvasRenderer]);
const props=defineProps<{cycles:any[],departments:any[],cycleId:string,departmentId:string}>();
const emit=defineEmits<{(e:'update:cycleId',v:string):void;(e:'update:departmentId',v:string):void}>();
const rows=ref<any[]>([]),history=ref<any[]>([]),summary=ref<any>(null),error=ref(''),loading=ref(false);let serial=0;
async function load(){const seq=++serial;rows.value=[];history.value=[];summary.value=null;error.value='';if(!props.cycleId||!props.departmentId)return;loading.value=true;const q=`cycleId=${encodeURIComponent(props.cycleId)}&departmentId=${encodeURIComponent(props.departmentId)}`;try{const [s,r,h]=await Promise.all([managementRequest(`management/insights-summary?${q}`),managementRequest(`management/archives?${q}`),managementRequest(`management/archives?departmentId=${encodeURIComponent(props.departmentId)}`)]);if(seq!==serial)return;summary.value=s;rows.value=r;history.value=h;}catch(e){if(seq===serial)error.value=e instanceof Error?e.message:'加载失败';}finally{if(seq===serial)loading.value=false;}}
watch(()=>[props.cycleId,props.departmentId],load,{immediate:true});
const bands=[{label:'90–100 分',min:90,max:101,color:'#3268ed'},{label:'80–89 分',min:80,max:90,color:'#76a3ff'},{label:'60–79 分',min:60,max:80,color:'#a9c5ff'},{label:'0–59 分',min:0,max:60,color:'#ff9472'}];
const scores=computed(()=>rows.value.map(r=>r.payload_json?.final_score).filter(v=>v!==null&&v!==undefined&&Number.isFinite(Number(v))).map(Number));
const distribution=computed(()=>bands.map(b=>({...b,count:scores.value.filter(v=>v>=b.min&&v<b.max).length})));
const pie=computed(()=>({tooltip:{trigger:'item'},series:[{type:'pie',radius:['60%','78%'],center:['50%','50%'],label:{show:false},data:distribution.value.map(d=>({name:d.label,value:d.count,itemStyle:{color:d.color}}))}]}));
const dimensions=computed(()=>{const map=new Map<string,{label:string,peer:number[],self:number[]}>();for(const row of rows.value)for(const [key,field] of [['peer_items','peer'],['self_items','self']] as const)for(const item of row.payload_json?.[key]??[]){if(!item.label)continue;const d=map.get(item.label)??{label:item.label,peer:[] as number[],self:[] as number[]};if(item.avg_score!==null&&item.avg_score!==undefined&&Number.isFinite(Number(item.avg_score)))d[field].push(Number(item.avg_score));map.set(item.label,d);}return [...map.values()].map(d=>({label:d.label,peer:d.peer.length?d.peer.reduce((a,b)=>a+b,0)/d.peer.length:null,self:d.self.length?d.self.reduce((a,b)=>a+b,0)/d.self.length:null}));});
const trend=computed(()=>{const groups=new Map<string,number[]>();for(const r of history.value){const score=r.payload_json?.final_score;if(score===null||score===undefined||!Number.isFinite(Number(score)))continue;const key=r.month;groups.set(key,[...(groups.get(key)??[]),Number(score)]);}return [...groups].sort(([a],[b])=>a.localeCompare(b)).map(([month,values])=>({month,average:values.reduce((a,b)=>a+b,0)/values.length}));});
const line=computed(()=>({tooltip:{trigger:'axis'},grid:{left:45,right:24,top:25,bottom:36},xAxis:{type:'category',data:trend.value.map(x=>x.month)},yAxis:{type:'value',min:0,max:100,splitLine:{lineStyle:{color:'#edf2f8'}}},series:[{type:'line',data:trend.value.map(x=>Number(x.average.toFixed(2))),smooth:true,symbolSize:7,itemStyle:{color:'#326cff'},areaStyle:{color:'rgba(80,140,255,.12)'}}]}));
const bars=computed(()=>({tooltip:{trigger:'axis'},grid:{left:80,right:45,top:15,bottom:20},xAxis:{type:'value',min:0,max:100,show:false},yAxis:{type:'category',inverse:true,data:dimensions.value.map(x=>x.label),axisLine:{show:false},axisTick:{show:false}},series:[{type:'bar',barWidth:9,showBackground:true,backgroundStyle:{color:'#edf2f8'},label:{show:true,position:'right',formatter:(p:any)=>p.value==null?'—':Number(p.value).toFixed(2)},itemStyle:{color:'#3974f4',borderRadius:5},data:dimensions.value.map(x=>x.peer)}]}));
</script>
<template><div class="insights"><div class="filters"><label>周期 <select :value="cycleId" @change="emit('update:cycleId',($event.target as HTMLSelectElement).value)"><option v-for="c in cycles" :key="c.id" :value="c.id">{{c.title}} · {{c.month}}</option></select></label><label>部门 <select :value="departmentId" @change="emit('update:departmentId',($event.target as HTMLSelectElement).value)"><option v-for="d in departments" :key="d.id" :value="d.id">{{d.name}}</option></select></label></div><p v-if="error" role="alert">{{error}} <button class="btn" @click="load">重试</button></p><p v-else-if="loading" role="status">正在加载数据…</p><template v-else-if="summary"><div class="stats"><div v-for="s in [{name:'应参评人数',value:summary.participants,icon:'♙'},{name:'已提交月报',value:summary.materials,icon:'✓'},{name:'已发布成绩',value:summary.published,icon:'▥'},{name:'月报提交率',value:summary.materialRate==null?'—':(summary.materialRate*100).toFixed(1)+'%',icon:'▤'}]" :key="s.name" class="metric"><span class="icon">{{s.icon}}</span><div><strong>{{s.value}}</strong><small>{{s.name}}</small></div></div></div><div class="grid"><section class="panel"><h2>本部门正式成绩分布</h2><div v-if="scores.length" class="distribution"><div class="donut"><VChart :option="pie" autoresize class="chart"/><div class="center">成绩分布<br><b>{{scores.length}} 人</b></div></div><div class="legend"><div v-for="d in distribution" :key="d.label"><i :style="{background:d.color}"/>{{d.label}} <span>{{d.count}} 人（{{(d.count/scores.length*100).toFixed(1)}}%）</span></div></div></div><p v-else class="empty">暂无正式发布成绩</p></section><section class="panel"><h2>维度与自他评差异</h2><div class="table-wrap"><table><thead><tr><th>维度</th><th>他评均分</th><th>自评均分</th><th>差值（自评－他评）</th></tr></thead><tbody><tr v-for="d in dimensions" :key="d.label"><td>{{d.label}}</td><td>{{d.peer?.toFixed(2)??'—'}}</td><td>{{d.self?.toFixed(2)??'—'}}</td><td>{{d.self!=null&&d.peer!=null?(d.self-d.peer).toFixed(2):'—'}}</td></tr></tbody></table></div><p v-if="!dimensions.length" class="empty">暂无维度数据</p></section><section class="panel"><h2>本部门历史趋势</h2><VChart v-if="trend.length" :option="line" autoresize class="trend-chart"/><p v-else class="empty">暂无历史发布成绩</p></section><section class="panel"><h2>本周期维度表现</h2><VChart v-if="dimensions.some(d=>d.peer!=null)" :option="bars" autoresize class="trend-chart"/><p v-else class="empty">暂无他评维度数据</p></section></div></template><p v-else>请选择可查看的周期和部门</p></div></template>
<style scoped>
.insights{color:#182d4e}.filters{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:18px}.filters label{display:flex;align-items:center;gap:8px;color:#687a94}.filters select{height:36px;max-width:320px;border:1px solid #dce5f1;border-radius:6px;background:#fff;padding:0 10px;color:#233a5f}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:16px}.metric,.panel{background:#fff;border:1px solid #e1e9f4;border-radius:10px;box-shadow:0 2px 6px #233a5b06}.metric{display:flex;gap:16px;align-items:center;padding:18px 22px}.metric strong{display:block;font-size:23px}.metric small{color:#647795}.icon{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;background:#edf4ff;color:#3370ff;font-size:22px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.panel{padding:20px;min-width:0}.panel h2{font-size:16px;margin:0 0 12px}.distribution{display:flex;align-items:center;justify-content:space-around;gap:18px}.donut{position:relative;width:190px;height:190px;flex:none}.chart{width:100%;height:100%}.center{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;pointer-events:none;text-align:center;font-size:12px}.legend{min-width:180px}.legend div{display:flex;align-items:center;gap:8px;padding:8px 0;font-size:12px}.legend i{width:9px;height:9px;border-radius:50%}.legend span{margin-left:auto}.trend-chart{width:100%;height:200px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:11px 10px;text-align:left;white-space:nowrap;border-bottom:1px solid #eef2f7}th{background:#f4f7fc;color:#71819a}.empty{height:190px;display:grid;place-items:center;color:#8796aa;font-size:13px}@media(max-width:1000px){.stats{grid-template-columns:repeat(2,1fr)}.distribution{flex-wrap:wrap}}@media(max-width:750px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.metric{padding:14px}.filters select{max-width:100%}}
</style>

